import { PieArcDatum, ProvidedProps } from '@visx/shape/lib/shapes/Pie';
import React, { memo } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { useFormatter } from '../context/FormatterContext.js';
import { useLabels } from '../context/LabelsContext.js';
import { labelPosition } from '../functions/label-position.js';
import { sliceAngleDistance } from '../functions/slice-angle-distance.js';
import { LABEL_FONT_SIZE } from '../types/default.js';
import { InternalSliceData } from '../types/internal/pie-chart.js';
import { getLabelTextAnchor } from '../utils/get-label-text-anchor.js';

export interface PieLabelProps {
  arc: PieArcDatum<{ category: string; value: number } & InternalSliceData>;
  data: InternalSliceData;
  path: ProvidedProps<InternalSliceData>['path'];
}

const MAX_CHAR_ALLOWED = 6;

export const PieChartLabel = memo((props: PieLabelProps) => {
  const { path, arc, data } = props;
  const { valueType } = useLabels();
  const formatter = useFormatter();
  const outerRadius = path.outerRadius()(arc);
  const innerRadius = path.innerRadius()(arc);
  const [centroidX, centroidY] = path.centroid(arc);
  const sliceAngleInPixels = sliceAngleDistance(
    arc.endAngle - arc.startAngle,
    outerRadius,
  );
  const { labelX, labelY } = labelPosition({
    outerRadius,
    innerRadius,
    centroidX,
    centroidY,
  });

  const formatLabelText = (): string => {
    if (valueType === 'absolute') {
      return formatter(data.value);
    }

    return `${data.relativeValue.toFixed(0)}%`;
  };

  const labelText = formatLabelText();

  const showLabel = (): boolean => {
    const labelFitsSliceSize = sliceAngleInPixels >= LABEL_FONT_SIZE * 2;
    if (valueType === 'relative') {
      return labelFitsSliceSize;
    }
    const labelTextFitsMaxChar =
      labelText.toString().length <= MAX_CHAR_ALLOWED;

    return labelTextFitsMaxChar && labelFitsSliceSize;
  };

  const labelTextAnchor = getLabelTextAnchor(labelX, labelY);

  return showLabel() ? (
    <text
      fill={Colors.Text.Neutral.Default}
      x={labelX}
      y={labelY}
      fontSize={LABEL_FONT_SIZE}
      textAnchor={labelTextAnchor}
      pointerEvents="none"
    >
      {labelText}
    </text>
  ) : null;
});
